"""Record the latest user requirements without restarting PCB engineering."""
from pathlib import Path
import json,hashlib
root=Path.cwd();out=root/'reports/pre-hardware-characterization-20261001/requirement-sync-r01';out.mkdir(exist_ok=False)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
registry='reports/pre-hardware-characterization-20261001/characterization-register-r01/requirements-and-coverage.json'
sheet='reports/pre-hardware-characterization-20261001/characterization-register-r01/provisional-datasheet.json'
items={
 'PROJECT_MEMORY.md':f'**Pre-hardware characterization and virtual bench (user, 1 October 2026):** before fabrication, characterize failure boundaries and component hard limits for STEP/encoder/SPI/servo/input/output/power/analog/watchdog/startup/thermal behavior, with voltage/temperature/tolerance corners and simultaneous full load. Build one disconnected command around actual CNC3/HAL and actual Verilated RTL, mechanical/ABZ/home/probe/fault models, nine machine profiles, electrical simulation and vendor fit/timing. Record DESIGN LIMIT, SIMULATED LIMIT, DATASHEET LIMIT and PHYSICAL VALIDATION REQUIRED separately; no simulation-only hardware ratings. This adds verification to the existing single-board work. [Exact 15-subsystem/22-fault coverage]({registry}); [provisional engineering datasheet]({sheet}). First actual twelve-generator sweep passes 144 cases and 7,077,888 edge/count comparisons, including exact DDS boundary checks; four copied-RTL mutation controls detect real faults. This is isolated pulse-generator evidence; complete CNC3/HAL/twelve-joint runtime, SPICE and Efinity remain unfinished. Exploratory 12/12-tick timing has effectively no margin at 2 MHz; production defaults/rate limits are unchanged.',
 'docs/BUILD_PLAN.md':f'**Added pre-fabrication acceptance work, 1 October 2026:** integrate the [characterization register](../{registry}) alongside routing, source correction and manufacturing checks. Preserve actual source/RTL and test their limits with named corners, every emitted pulse counted, retained failing seeds/traces and explicit missing-model failures. Complete real CNC3/HAL-to-Verilated RTL, mechanical plant and fault/UX profiles before claiming a complete virtual machine. Run source-bound circuit simulations and Efinity device fit/static timing; qualify final routed trace/return/cable/power geometry. Generate conservative provisional ratings only where all relevant limits are supported, then confirm/derate with Rev A. The first component sweep and mutation controls are implemented; the full virtual controller and electrical qualification are not.',
 'docs/PLATFORM_ROADMAP.md':f'**Pre-production characterization scope, 1 October 2026:** the [preserved latest requirements](../{registry}) add failure-boundary sweeps, corners, full-load virtual integration, actual-RTL mechanical/fault models and pre-hardware datasheet evidence. These are acceptance obligations, not advertised capabilities. The first twelve-instance pulse-generator sweep is component HDL evidence; neither the twelve-channel endpoint nor hardware 2 MHz operation follows from that result. Existing machine/display/module/commercial scope remains in force.',
 'reports/ENGINEERING_STATUS.md':f'**Pre-hardware bench work, 1 October 2026:** [actual twelve-generator HDL sweep](pre-hardware-characterization-20261001/stepgen12-sweep-r02/receipt.json) passes 144 scenarios and 7,077,888 edge/count comparisons. Three explicit timing profiles sweep from 100 kHz through 4 MHz and test the integer DDS safe/failure boundary in both directions and reset-reachable worst phases. At assumed 50 MHz, default 100/100 ticks permits 248,756.213 pulses/s at the isolated generator; experimental 12/12 permits 1,999,999.990 and 9/9 permits 2,631,578.944. These are component simulation limits, not product ratings. The historical CNC1 endpoint remains capped at 195,312.5 pulses/s. [Four actual compiled-copy fault controls](pre-hardware-characterization-20261001/stepgen12-mutation-controls-r02/receipt.json) pass; original production RTL is unchanged. [Coverage and missing work](pre-hardware-characterization-20261001/characterization-register-r01/requirements-and-coverage.json) accounts for 15 subsystems, 22 injected-fault cases, plant faults and nine machine profiles. Full CNC3/HAL-to-RTL, SPICE and vendor fit/timing are unfinished. [Provisional datasheet](pre-hardware-characterization-20261001/characterization-register-r01/provisional-datasheet.json) has no hardware-qualified rating.'
}
changes=[]
for name,paragraph in items.items():
 p=root/name;old=p.read_text(encoding='utf8');before=sha(p)
 assert paragraph not in old
 first,rest=old.split('\n',1);new=first+'\n\n'+paragraph+'\n'+rest
 (out/(p.name+'.before')).write_bytes(p.read_bytes());p.write_text(new,encoding='utf8')
 changes.append(dict(path=name,before_sha256=before,after_sha256=sha(p)))
p=root/'docs/CURRENT_ACCEPTANCE_GATES.md';old=p.read_text(encoding='utf8');before=sha(p)
(out/(p.name+'.before')).write_bytes(p.read_bytes())
start=old.index('**Current evidence boundary:**');end=old.index('\n\n## Mandatory product gates',start)
boundary='**Current evidence boundary (1 October 2026):** adopted Source26/ROOT101 has 2,688 footprints, 1,734 multi-pad nets (632 fully joined, 1,102 incomplete), 3,528 independently counted missing joins, zero orphan copper and native DRC zero errors/warnings with no ignored checks. Source26 ERC has zero errors and 70 unsuppressed warnings. The source represents all twelve motor interfaces, four ABZ paths, 24 DI, 16 smart DO and the remaining frozen I/O/compute/service functions; full routing/runtime/physical qualification is unfinished. Source27 reset/slow-input corrections are staged, not adopted. Fresh ROOT101 regression passed 1,847 host and 235 actual KiCad cases; five Windows symlink cases remain skipped. [Adopted routing WIP](../reports/motherboard-pcb-integration-20261001/source26-BankA-health-U25-C19033-merged-trial-r101/adoption.json). The older 327-part MC r0.4 and six/two runtime remain historical evidence. Native cleanliness is not manufacturing readiness.'
new=old[:start]+boundary+old[end:]
replacements={
 'Open. Runtime remains historical six/two. MC r0.4 includes twelve STEP/DIR/enable Ioff paths and two TX paths; receiver interfaces, alarms, expanded RTL/driver/runtime and physical qualification remain incomplete.':'Open. Source26 represents all twelve STEP/DIR, enable and alarm interfaces; 3,528 required board joins remain. Complete CNC3/RTL/HAL and vendor/physical qualification remain unfinished. Historical runtime is six/two.',
 'Open. Historical input sheet has 22 total inputs; current partial MC does not implement the promised 24 general DI/16 general DO product.':'Open. Source26 represents 24 general DI and 16 smart DO with acquisition/control circuitry. Full routing, actual concurrent I/O runtime and electrical/thermal qualification remain unfinished.',
 'Open. No complete per-output measurement path or deployed measurement UI.':'Open. Source26 represents output current/fault acquisition paths. Complete routing, calibration, actual firmware/transport and deployed validity/age UI remain unqualified.',
 'Open. MC r0.4 has 97 incomplete multi-pad nets/711 missing physical joins plus omitted circuits and unqualified physical behavior. [Current cost](../reports/board-completion-20260930/mc-bom-cost-r04/MC_BOM_COST.md) prices 42/52 MPNs with two MOQ lines; full/stock-covered totals remain null. Current manifest/checklist still blocks prototype and production (17/23 blockers). No fabrication placeholders or manufacturing-ready claim.':'Open. Source26/ROOT101 has 1,102 incomplete multi-pad nets and 3,528 required joins. [Current partial BOM](../reports/motherboard-cost-20260930/source-r26-2688-complete-cost-v11/README.md) leaves 185 MPNs/720 purchased pieces unpriced; complete assembly/module/screen cost and manufacturer quotes remain missing. No Gerber/drill/final assembly release or manufacturing-ready claim.',
 'New user target, open. Historical six-channel 195,312.5 pulses/s evidence and analytical 25-tick timing do not qualify this target. No hardware rating or runtime limit is raised by recording it.':'Open. New isolated twelve-generator HDL sweep passes 144 cases and exact DDS boundary checks; experimental 12/12 ticks has effectively no margin at 2 MHz. Complete twelve-channel CNC3 endpoint, dynamic timing profiles, actual driver/cable timing, target load and hardware qualification remain unfinished. Historical six-channel 195,312.5 pulses/s runtime limit is unchanged.'
}
for a,b in replacements.items():
 assert new.count(a)==1,a
 new=new.replace(a,b)
marker='\n\nEach gate needs exact input revision'
assert marker in new
gate='\n| G25 | Pre-fabrication performance limits and one-command virtual bench, with simulated/design/datasheet/physical evidence kept separate | [15-subsystem characterization register](../'+registry+'), exact-source actual RTL/CNC3/HAL integration, all12 pulse counts and dynamic profiles, nine mechanical/UX machine profiles,22 fault cases, voltage/temperature/tolerance corners, concurrent worst load, source-bound SPICE, final-route SI/power/thermal and Efinity fit/static timing; retain seeded failure traces and provisional datasheet without invented qualified ratings | Partial component evidence:144 twelve-generator scenarios plus four real copied-RTL mutation controls pass. Actual complete CNC3 endpoint/HAL and full electrical/vendor/physical stages remain unfinished. |'
new=new.replace(marker,gate+marker)
p.write_text(new,encoding='utf8');changes.append(dict(path=str(p.relative_to(root)),before_sha256=before,after_sha256=sha(p)))
(out/'receipt.json').write_text(json.dumps(dict(passed=True,changes=changes,no_source_firmware_RTL_or_board_changes=True,requirements_preserved_in_registry=True),indent=2)+'\n')
print(json.dumps(dict(passed=True,files=len(changes))))
